"use client";

import { ArrowRight, Clock3, Inbox, Mail, MapPin, MessageSquareText, Phone, Search, ShieldCheck, UserRound } from "lucide-react";
import { useActionState, useMemo, useState } from "react";
import Link from "next/link";
import { createAdvisorFeedbackAction, transitionInquiryAction } from "@/app/dashboard/actions";
import { SectionHeader } from "@/components/dashboard/page-header";
import { initialActionState } from "@/lib/dashboard/validation";
import {
  filterConversationRecords,
  selectVisibleConversation,
  type ConversationView,
} from "@/lib/dashboard/filters";

export type InquiryRecord = {
  id: string;
  full_name: string;
  email: string | null;
  phone: string | null;
  message: string | null;
  status: string;
  consent_at: string;
  consent_purpose: string | null;
  property_id: string | null;
  search_run_id: string | null;
  created_at: string;
  property: { name: string; location: string; price_aed: number } | null;
};

const openStatuses = new Set(["new", "qualified", "contacted", "viewing_booked"]);

function formatAed(value: number) {
  return new Intl.NumberFormat("en-AE", { style: "currency", currency: "AED", maximumFractionDigits: 0 }).format(value);
}

function InquiryStatusForm({ inquiry }: { inquiry: InquiryRecord }) {
  const [state, action, pending] = useActionState(transitionInquiryAction, initialActionState);

  return <form action={action} className="ops-dossier-action">
    <input type="hidden" name="inquiryId" value={inquiry.id} />
    <label>Next status<select name="status" defaultValue={inquiry.status} aria-label={`Status for ${inquiry.full_name}`}><option value="new">New</option><option value="qualified">Qualified</option><option value="contacted">Contacted</option><option value="viewing_booked">Viewing booked</option><option value="closed">Closed</option><option value="spam">Spam</option></select></label>
    <button type="submit" disabled={pending}>{pending ? "Updating…" : "Update conversation"}</button>
    {state.message ? <small data-status={state.status} role="status">{state.message}</small> : null}
  </form>;
}

function AdvisorFeedbackForm({ inquiry }: { inquiry: InquiryRecord }) {
  const [state, action, pending] = useActionState(createAdvisorFeedbackAction, initialActionState);
  return <form action={action} className="ops-dossier-action">
    <input type="hidden" name="inquiryId" value={inquiry.id} />
    <label>Evidence feedback<select name="category" defaultValue="missing_evidence"><option value="missing_evidence">Missing evidence</option><option value="wrong_criterion">Wrong criterion</option><option value="stale_source">Stale source</option><option value="handoff_outcome">Handoff outcome</option></select></label>
    <label>Outcome<select name="outcome" defaultValue=""><option value="">Not set</option><option value="useful">Useful</option><option value="needs_follow_up">Needs follow-up</option><option value="not_a_fit">Not a fit</option><option value="contacted">Contacted</option><option value="viewing_booked">Viewing booked</option><option value="closed">Closed</option></select></label>
    <label>Evidence-quality note<textarea name="notes" maxLength={1000} placeholder="Describe the missing, incorrect, or stale evidence without adding unnecessary buyer data." /></label>
    <button type="submit" disabled={pending}>{pending ? "Saving…" : "Save evidence feedback"}</button>
    {state.message ? <small data-status={state.status} role="status">{state.message}</small> : null}
  </form>;
}

export function ConversationsWorkspace({ inquiries, canManage, initialView = "all" }: { inquiries: InquiryRecord[]; canManage: boolean; initialView?: ConversationView }) {
  const [query, setQuery] = useState("");
  const [view, setView] = useState<ConversationView>(initialView);
  const [selectedId, setSelectedId] = useState(inquiries[0]?.id ?? "");
  const filtered = useMemo(() => filterConversationRecords(inquiries, query, view), [inquiries, query, view]);
  const selected = selectVisibleConversation(filtered, selectedId);
  const needsReply = inquiries.filter((inquiry) => inquiry.status === "new").length;
  const active = inquiries.filter((inquiry) => openStatuses.has(inquiry.status)).length;

  if (!inquiries.length) return <section className="ops-conversation-empty" aria-labelledby="conversations-empty"><div className="ops-conversation-empty-copy"><span><Inbox aria-hidden="true" />Advisor queue</span><h2 id="conversations-empty">No consented handoffs yet.</h2><p>When a buyer asks Rama for an advisor, their selected residence, normalized brief, contact permission, and conversation context will arrive here together.</p><Link href="/" target="_blank" rel="noopener noreferrer">Test the buyer handoff <ArrowRight aria-hidden="true" /><span className="sr-only"> in a new tab</span></Link></div><ol aria-label="Buyer handoff journey"><li><span>01</span><strong>Buyer asks Rama</strong><small>Voice or text becomes an explainable property brief.</small></li><li><span>02</span><strong>Rama presents evidence</strong><small>Only eligible records and published facts are shown.</small></li><li><span>03</span><strong>Buyer gives consent</strong><small>The advisor receives the chosen property and conversation context.</small></li></ol></section>;

  return <section className="ops-conversations" aria-labelledby="conversation-heading">
    <SectionHeader eyebrow="Advisor queue" title="Buyer conversations" meta={`${needsReply} need a reply · ${active} active`} />
    <div className="ops-conversation-workspace">
      <aside className="ops-inquiry-queue" aria-label="Buyer inquiry queue">
        <label><Search aria-hidden="true" /><span className="sr-only">Search buyer conversations</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search buyer or residence" /></label>
        <div className="ops-queue-tabs" aria-label="Conversation views"><button type="button" data-active={view === "all"} aria-pressed={view === "all"} onClick={() => setView("all")}>All <strong>{inquiries.length}</strong></button><button type="button" data-active={view === "needs_reply"} aria-pressed={view === "needs_reply"} onClick={() => setView("needs_reply")}>Needs reply <strong>{needsReply}</strong></button></div>
        <div className="ops-queue-list">{filtered.map((inquiry) => <button key={inquiry.id} type="button" data-selected={selected?.id === inquiry.id} onClick={() => setSelectedId(inquiry.id)}><span className="ops-avatar" aria-hidden="true">{inquiry.full_name.slice(0, 1).toUpperCase()}</span><span><strong>{inquiry.full_name}</strong><small>{inquiry.property?.name ?? "Residence context unavailable"}</small><em>{inquiry.message || "Advisor follow-up requested."}</em></span><span><small>{new Intl.DateTimeFormat("en-AE", { month: "short", day: "numeric" }).format(new Date(inquiry.created_at))}</small><i className="ops-status" data-status={inquiry.status}>{inquiry.status.replace("_", " ")}</i></span></button>)}</div>
        {!filtered.length ? <div className="ops-queue-empty"><Search aria-hidden="true" /><strong>No conversations match.</strong><span>Clear the search or open another view.</span><button type="button" onClick={() => { setQuery(""); setView("all"); }}>Clear filters</button></div> : null}
      </aside>

      {selected ? <article className="ops-buyer-dossier">
        <header><div className="ops-dossier-identity"><span className="ops-avatar" aria-hidden="true">{selected.full_name.slice(0, 1).toUpperCase()}</span><div><p>Buyer dossier</p><h2 id="conversation-heading">{selected.full_name}</h2><span>{selected.email || selected.phone || "No contact channel"}</span></div></div><span className="ops-status" data-status={selected.status}>{selected.status.replace("_", " ")}</span></header>
        <div className="ops-dossier-facts"><div><Mail aria-hidden="true" /><span><small>Email</small><strong>{selected.email || "Not provided"}</strong></span></div><div><Phone aria-hidden="true" /><span><small>Phone</small><strong>{selected.phone || "Not provided"}</strong></span></div><div><Clock3 aria-hidden="true" /><span><small>Consent</small><strong>{new Intl.DateTimeFormat("en-AE", { dateStyle: "medium", timeStyle: "short" }).format(new Date(selected.consent_at))}</strong></span></div></div>
        <section className="ops-dossier-section"><p>What the buyer asked</p><blockquote>{selected.message || "Advisor follow-up requested."}</blockquote>{selected.search_run_id ? <small>Discovery run {selected.search_run_id.slice(0, 8)}</small> : null}</section>
        <section className="ops-dossier-section"><p>Residence in context</p>{selected.property ? <div className="ops-linked-property"><div><MapPin aria-hidden="true" /><span><strong>{selected.property.name}</strong><small>{selected.property.location}</small></span></div><strong>{formatAed(selected.property.price_aed)}</strong></div> : <div className="ops-context-gap"><MessageSquareText aria-hidden="true" /><span><strong>Property context unavailable</strong><small>The catalog record may have been removed after the handoff.</small></span></div>}</section>
        <section className="ops-dossier-section"><p>Consent and governance</p><div className="ops-consent-note"><ShieldCheck aria-hidden="true" /><span><strong>Explicit advisor handoff</strong><small>{selected.consent_purpose || "Buyer requested advisor follow-up."}</small></span></div></section>
        {canManage ? <><InquiryStatusForm key={`status:${selected.id}`} inquiry={selected} /><AdvisorFeedbackForm key={`feedback:${selected.id}`} inquiry={selected} /></> : <div className="ops-read-only"><UserRound aria-hidden="true" />Your role can inspect this dossier but cannot change its status.</div>}
      </article> : null}
    </div>
  </section>;
}
